/// <reference types="react" />
import * as CSS from 'csstype';
import type { GroupBase, OptionsOrGroups } from 'react-select';
import type { DataTestId } from '../../core/types/data-props.js';
import type { StylingProps } from '../../core/types/styling-props.js';
export type SelectV2SingleValue<OptionValue> = OptionValue | null;
export type SelectV2MultiValue<OptionValue> = OptionValue[];
export type SingleOrMultiValue<OptionValue> = SelectV2MultiValue<OptionValue> | SelectV2SingleValue<OptionValue>;
/**
 * Internal type for the Option data
 *
 * @internal
 */
export interface _BaseOption<OptionValue> extends StylingProps, DataTestId {
    label?: React.ReactNode;
    value: OptionValue;
    isDisabled?: boolean;
    /**
     * Prefix passed to the option
     */
    prefix: {
        component: React.ReactNode | null;
        componentProps?: StylingProps & DataTestId;
    };
    /**
     * Suffix passed to the option
     */
    suffix: {
        component: React.ReactNode | null;
        componentProps?: StylingProps & DataTestId;
    };
    textValue?: string;
    'aria-label'?: string;
}
/**
 * Internal type for Group data
 * @internal
 */
export interface _BaseGroup<OptionValue> extends StylingProps, DataTestId {
    label?: string;
    options: _BaseOption<OptionValue>[];
    labelProps?: StylingProps & DataTestId;
}
/**
 * Internal type combining either Options or groups
 *
 * @internal
 */
export type _OptionOrGroup<OptionValue> = OptionsOrGroups<OptionValue, GroupBase<OptionValue>>;
export type SelectTriggerWidthOptionsType = 'content' | 'full' | CSS.Property.Width<string & {}>;
export type SelectContentWidthOptionsType = 'trigger' | CSS.Property.Width<string & {}>;
